
import type { NextActionInput } from './NextActionInput.js';

export type ResponseWarningInput = { "code": string; "context"?: Record<string, string>; "message": string; "next_actions"?: Array<NextActionInput>; /** RFC3339 timestamp. Format: date-time. */ "observed_at"?: string | globalThis.Date; /** Promotion code that was accepted but did not apply, on a promotion_declined warning. */ "promotion_code"?: string; /** Stable Flint reason code. On a promotion_declined warning this is the promotion decline reason (for example superseded_by_better_offer); an unrecognized value falls back to not_eligible. See the Promotions reference for the full list. */ "reason"?: "already_applied" | "automatic_disabled" | "buy_item_missing" | "code_invalid" | "code_required" | "codes_disabled" | "currency_mismatch" | "disabled" | "exhausted" | "expired" | "max_promotions_reached" | "minimum_not_met" | "no_discountable_balance" | "not_combinable" | "not_eligible" | "not_yet_started" | "superseded" | "superseded_by_better_offer" | "unknown_type"; "resource"?: string; "resource_id"?: string; "severity"?: string; /** Discount amount this promotion would have applied had it won, on a promotion_declined warning. */ "would_have_applied_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; };
